"""Independent (Fraction-based, enumeration-driven) reference for the spec."""
from fractions import Fraction

MODES = ("RNE", "RNA", "RTZ", "RUP", "RDN")


def _decode(v, ebits, fbits):
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    s = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & Eall
    f = v & (F - 1)
    if e == Eall:
        if f == 0:
            return ("inf", None, s)
        return ("nan", 1 if (f >> (fbits - 1)) & 1 else 0, s)
    if e == 0:
        return ("zero" if f == 0 else "fin",
                Fraction(f) * Fraction(2) ** (1 - bias - fbits), s)
    return ("fin", Fraction(F + f) * Fraction(2) ** (e - bias - fbits), s)


def _floor_log2(x):
    n, d = x.numerator, x.denominator
    L = n.bit_length() - d.bit_length()
    if L >= 0:
        if n < (d << L):
            L -= 1
    else:
        if (n << (-L)) < d:
            L -= 1
    return L


def _encode_value(y, ebits, fbits):
    """Encode a nonnegative Fraction that is exactly representable."""
    F = 1 << fbits
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    if y == 0:
        return 0
    L = _floor_log2(y)
    # normalized candidate
    e = L + bias
    if e >= 1:
        s = y / Fraction(2) ** (L - fbits)
        assert s.denominator == 1
        si = s.numerator
        assert F <= si < 2 * F, (y, L, si)
        return (e << fbits) | (si - F)
    # subnormal
    q = Fraction(2) ** (1 - bias - fbits)
    si = y / q
    assert si.denominator == 1 and si.numerator < F
    return si.numerator


